0004     // Shared contact ledger: one hit per attack group, with an explicit GD02 parry contract.
0005     public sealed class KarmaAttackContact
0006     {
0007         public bool BreaksShieldOnParry { get; private set; }
0008         public KarmaAttackContact(bool breaksShieldOnParry = false) { BreaksShieldOnParry = breaksShieldOnParry; }
0009         public bool Consumed { get; private set; }
0010         public bool DealtDamage { get; private set; }
0011         public void RecordDamage() { DealtDamage = true; }
0012         public bool TryConsume() { if (Consumed) return false; Consumed = true; return true; }
