0014     public sealed class KarmaTrialState
0015     {
0016         public bool Active { get; private set; }
0017         public int Hits { get; private set; }
0018         public int Completed { get; private set; }
0019         public int Total { get; private set; }
0020         public int Allowed { get; private set; }
0021         public bool Finished { get { return Active && Completed >= Total; } }
0022         public bool Passed { get { return Finished && Hits <= Allowed; } }
0023         public void Begin(int total, int allowed)
0024         { Total = Math.Max(1, total); Allowed = Math.Max(0, allowed); Hits = Completed = 0; Active = true; }
0025         public void Hit() { if (Active && !Finished) Hits++; }
0026         public void CompleteAttack() { if (Active && !Finished) Completed++; }
0027         public void Clear() { Active = false; Hits = Completed = Total = Allowed = 0; }
0028     }
0029     public static class KarmaBossGeometry
0030     {
0031         // Continuous SAT: a translating oriented attack rectangle versus an
0032         // axis-aligned player rectangle. No diagonal enclosing-box false hits.
0033         public static bool SweptOrientedBox(float ax, float ay, float bx, float by,
0034             float px, float py, float ux, float uy, float length, float thickness,
0035             float playerHalfWidth, float playerHalfHeight)
0036         {
0037             float first = 0, last = 1;
0038             float dx = ax - px, dy = ay - py, vx = bx - ax, vy = by - ay;
0039             float hx = length / 2, hy = thickness / 2;
0040             return Axis(dx, vx, Math.Abs(ux) * hx + Math.Abs(uy) * hy + playerHalfWidth, ref first, ref last)
0041                 && Axis(dy, vy, Math.Abs(uy) * hx + Math.Abs(ux) * hy + playerHalfHeight, ref first, ref last)
0042                 && Axis(dx * ux + dy * uy, vx * ux + vy * uy,
0043                     hx + Math.Abs(ux) * playerHalfWidth + Math.Abs(uy) * playerHalfHeight, ref first, ref last)
0044                 && Axis(-dx * uy + dy * ux, -vx * uy + vy * ux,
0045                     hy + Math.Abs(uy) * playerHalfWidth + Math.Abs(ux) * playerHalfHeight, ref first, ref last);
0046         }
0047         // Segment versus expanded AABB: exact swept rectangular attack, including target size.
0048         public static bool SweptBox(float ax, float ay, float bx, float by,
0049             float px, float py, float halfWidth, float halfHeight)
0050         {
0051             float first = 0, last = 1;
0052             return Axis(ax - px, bx - ax, halfWidth, ref first, ref last)
0053                 && Axis(ay - py, by - ay, halfHeight, ref first, ref last);
0054         }
0055         static bool Axis(float origin, float delta, float extent, ref float first, ref float last)
0056         {
0057             if (Math.Abs(delta) < 0.000001f) return Math.Abs(origin) <= extent;
0058             float a = (-extent - origin) / delta, b = (extent - origin) / delta;
0059             first = Math.Max(first, Math.Min(a, b)); last = Math.Min(last, Math.Max(a, b));
0060             return first <= last;
0061         }
0062     }
0063 }

0048         public static bool SweptBox(float ax, float ay, float bx, float by,
0049             float px, float py, float halfWidth, float halfHeight)
0050         {
0051             float first = 0, last = 1;
0052             return Axis(ax - px, bx - ax, halfWidth, ref first, ref last)
0053                 && Axis(ay - py, by - ay, halfHeight, ref first, ref last);
0054         }
0055         static bool Axis(float origin, float delta, float extent, ref float first, ref float last)
0056         {
0057             if (Math.Abs(delta) < 0.000001f) return Math.Abs(origin) <= extent;
0058             float a = (-extent - origin) / delta, b = (extent - origin) / delta;
0059             first = Math.Max(first, Math.Min(a, b)); last = Math.Min(last, Math.Max(a, b));
0060             return first <= last;
0061         }
0062     }
0063 }

