0012         { return a == EnemyAttack.SW05 || a == EnemyAttack.UP05 || a == EnemyAttack.GD05; }
0013         public static List<EnemyAttack> BuildCycle(IReadOnlyList<Essence> returned)
0014         {
0015             var result = new List<EnemyAttack>();
0016             var owned = new HashSet<Essence>(returned);
0017             if (returned.Count == 0) { result.Add(EnemyAttack.GroundStrike); return result; }
0018             switch (returned[0])
0019             {
0020                 case Essence.SwordWave:
0021                     result.Add(EnemyAttack.SW01); result.Add(EnemyAttack.SW02);
0022                     if (owned.Contains(Essence.RisingSlash)) result.Add(EnemyAttack.SW03);
0023                     if (owned.Contains(Essence.Guard)) result.Add(EnemyAttack.SW04);
0024                     if (owned.Count == 3) result.Add(EnemyAttack.SW05);
0025                     break;
0026                 case Essence.RisingSlash:
0027                     result.Add(EnemyAttack.GroundStrike);
0028                     result.Add(EnemyAttack.UP01); result.Add(EnemyAttack.UP02);
0029                     if (owned.Contains(Essence.SwordWave)) result.Add(EnemyAttack.UP03);
0030                     if (owned.Contains(Essence.Guard)) result.Add(EnemyAttack.UP04);
0031                     if (owned.Count == 3) result.Add(EnemyAttack.UP05);
0032                     break;
0033                 case Essence.Guard:
0034                     // GD01 is a separate periodic defense, never an attack in this cycle.
0035                     result.Add(EnemyAttack.GroundStrike); result.Add(EnemyAttack.GD02);
0036                     if (owned.Contains(Essence.SwordWave)) result.Add(EnemyAttack.GD03);
0037                     if (owned.Contains(Essence.RisingSlash)) result.Add(EnemyAttack.GD04);
0038                     if (owned.Count == 3) result.Add(EnemyAttack.GD05);
0039                     break;
0040             }
0041             return result;
0042         }
