0007     /// <summary>무의식화 여부와 선택 순서. 시간·입력·씬·이펙트에 의존하지 않음.</summary>
0008     public sealed class KarmaProgressionState
0009     {
0010         readonly bool[] remnants = new bool[3];
0011         readonly List<Essence> order = new List<Essence>();
0012         readonly ReadOnlyCollection<Essence> view;
0013         public KarmaProgressionState() { view = order.AsReadOnly(); }
0014         public IReadOnlyList<Essence> Order { get { return view; } }
0015         public int Count { get { return order.Count; } }
0016         public Essence? Pending { get; private set; }
0017         public bool Preview(Essence essence)
0018         {
0019             if (!HasActive(essence)) return false;
0020             Pending = essence; return true;
0021         }
0022         public void Cancel() { Pending = null; }
0023         public bool Confirm(out Essence essence)
0024         {
0025             essence = Pending ?? Essence.SwordWave;
0026             if (!Pending.HasValue || !TryInternalize(essence)) return false;
0027             Pending = null; return true;
0028         }
0029         public bool HasRemnant(Essence essence) { return remnants[Index(essence)]; }
0030         public bool HasActive(Essence essence) { return !HasRemnant(essence); }
0031         public bool TryInternalize(Essence essence)
0032         {
0033             int index = Index(essence);
0034             if (remnants[index]) return false;
0035             remnants[index] = true;
0036             order.Add(essence);
0037             return true;
0038         }
0039         static int Index(Essence essence)
0040         {
0041             int index = (int)essence;
0042             if (index < 0 || index >= 3) throw new ArgumentOutOfRangeException(nameof(essence));
0043             return index;
0044         }
0045     }
0046 }

