0005     {
0006         float slowUntil, shakeUntil;
0007         public void Trigger(float now, float slowSeconds, float shakeSeconds)
0008         {
0009             slowUntil = Math.Max(slowUntil, now + Math.Max(0, slowSeconds));
0010             shakeUntil = Math.Max(shakeUntil, now + Math.Max(0, shakeSeconds));
0011         }
0012         public float TimeScale(float now, bool combat, bool paused)
0013         {
0014             return paused ? 0 : combat && now < slowUntil ? 0.08f : 1;
0015         }
0016         public float Shake(float now, float seconds)
0017         {
0018             return seconds <= 0 ? 0 : Math.Max(0, Math.Min(1, (shakeUntil - now) / seconds));
0019         }
0020         public void Reset() { slowUntil = shakeUntil = 0; }
0021     }
0022     // Frame-rate independent travel curve: quick slash, then a soft deceleration.
0023     public sealed class KarmaAirSlashMotion
0024     {
0025         float elapsed, duration;
0026         public bool Active { get { return duration > 0 && elapsed < duration; } }
0027         public void Begin(float seconds) { elapsed = 0; duration = Math.Max(0.02f, seconds); }
0028         static float Distance(float t) { return (t - 0.25f * t * t) / 0.75f; }
0029         public float Advance(float seconds)
0030         {
0031             if (!Active || seconds <= 0) return 0;
0032             float before = elapsed / duration;
0033             elapsed = Math.Min(duration, elapsed + seconds);
0034             return Distance(elapsed / duration) - Distance(before);
0035         }
0036         public void Reset() { elapsed = duration = 0; }
0037     }
