0001 using UnityEngine;
0002 namespace KarmaPrototype
0003 {
0004     internal static class KarmaBossProjectileGeometry
0005     {
0006         internal static float SwordShotLife(Vector2 origin, Vector2 velocity, float life)
0007         {
0008             life = Mathf.Max(0, life);
0009             if (origin.x < KarmaStage.ArenaLeft || origin.x > KarmaStage.ArenaRight || origin.y < 0 || origin.y > KarmaSpace.Units(12)) return 0;
0010             if (velocity.x > 0) life = Mathf.Min(life, (KarmaStage.ArenaRight - origin.x) / velocity.x);
0011             else if (velocity.x < 0) life = Mathf.Min(life, (KarmaStage.ArenaLeft - origin.x) / velocity.x);
0012             if (velocity.y > 0) life = Mathf.Min(life, (KarmaSpace.Units(12) - origin.y) / velocity.y);
0013             else if (velocity.y < 0) life = Mathf.Min(life, -origin.y / velocity.y);
0014             return Mathf.Max(0, life);
0015         }
0016         internal static float AimedSlashBoundaryLife(Vector2 origin, Vector2 velocity, Vector2 size, float life)
0017         {
0018             if (velocity.x > 0) life = Mathf.Min(life, (KarmaStage.ArenaRight - size.x / 2 - origin.x) / velocity.x);
0019             else if (velocity.x < 0) life = Mathf.Min(life, (KarmaStage.ArenaLeft + size.x / 2 - origin.x) / velocity.x);
0020             return Mathf.Max(0, life);
0021         }
0022     }
0023 }

