0017                 // SW01 ends after two lanes; SW03 keeps its existing volley before the scars.
0018                 int shots = scars ? (owner.Enraged ? 4 : 3) : 2;
0019                 for (int i = 0; i < shots; i++)
0020                 {
0021                     Vector2 origin = i % 2 == 0 ? first : second;
0022                     var mark = owner.PathMark(origin, origin + velocity * sword.WaveLife, waveSize);
0023 
0024                     float warning = i == 0 ? owner.Warning(0.65f) : Mathf.Max(0.42f, 0.54f * owner.Tempo);
