0031                     yield return owner.Wait(warning);
0032                     owner.state = ActionState.Attack; owner.animator.Attack(); Destroy(mark.gameObject);
0033                     owner.Attack(origin, velocity, waveSize, sword.WaveLife);
0034                     if (!scars) sword.WaveLaunchVFX(origin, velocity, waveSize, false);
0035                     else { owner.animator.ReleaseWavePhase(); owner.animator.PlayWavePhase("Guard"); }
