0008         sealed class GroundStrikePattern : BossPattern
0009         {
0010             public GroundStrikePattern(KarmaEnemy owner) : base(owner) { }
0011             public override IEnumerator Execute()
0012             {
0013                 int count = owner.Enraged ? 3 : 2;
0014                 for (int i = 0; i < count && owner.Active; i++)
0015                 {
0016                     // Sample again BETWEEN swings; each orange warning locks its target.
0017                     float dx = owner.game.Player.Position.x - owner.Position.x;
0018                     owner.direction = dx < 0 ? -1 : 1;
0019                     owner.art.localScale = new Vector3(owner.direction * KarmaSpace.GuardianArtScale, KarmaSpace.GuardianArtScale, 1);
0020                     bool finish = i == count - 1;
0021                     float step = Mathf.Clamp(Mathf.Abs(dx) - KarmaSpace.Units(1.8f), 0, KarmaSpace.Units(finish ? 3 : 2));
0022                     Vector2 target = new Vector2(Mathf.Clamp(owner.Position.x + owner.direction * step, KarmaStage.BossLeftWall, KarmaStage.BossRightWall), owner.Position.y);
0023                     Vector2 size = KarmaSpace.Units(finish ? new Vector2(4.2f, 2.1f) : new Vector2(3.3f, 1.8f));
0024                     Vector2 center = target + Vector2.right * owner.direction * KarmaSpace.Units(1.6f);
0025                     owner.state = ActionState.Telegraph;
0026                     var mark = owner.Mark(finish ? "연속 베기 · 마무리" : "연속 베기 · 첫 타", center, size);
0027 
0028                     yield return owner.Wait(owner.Warning(i == 0 ? owner.game.Config.enemyTelegraphTime : 0.55f));
0029                     yield return owner.Motion(target, 0.16f, Vector2.zero);
0030                     Destroy(mark.gameObject); owner.animator.Attack(); owner.state = ActionState.Attack;
0031                     owner.Attack(center, Vector2.zero, size, 0.18f, finish ? 1.25f : 0.85f);
0032                     yield return owner.Wait(0.2f);
0033                 }
0034                 yield return owner.Recovery(0.85f);
0035             }
0036         }
